SEC.notices=async v=>{const ann=await load('ann');
 v.innerHTML='<div class="ac-box"><div class="ac-row"><h2 class="fit" style="align-self:center">Academic notices</h2><span class="fit"><button class="ac-btn" id="nadd">＋ New notice</button></span></div><p><small>Published notices appear on the public News &amp; announcements page under the Academic category.</small></p>'+(ann.map(a=>'<div class="ac-item"><div><b>'+esc(a.title)+'</b> '+pill(a.status,a.status==='published'?'ok':'warn')+'<br><small>'+fmt(a.published_at||a.created_at)+(a.audience_programme||a.audience_year?' · For: '+esc(a.audience_programme||'all programmes')+(a.audience_year?' · Year '+a.audience_year:''):' · All students')+'</small></div><div class="ac-row fit"><button class="ac-ghost" data-e="'+a.id+'">Edit</button>'+(a.status==='published'?'<button class="ac-ghost" data-s="'+a.id+'|archived">Archive</button>':'<button class="ac-btn" data-s="'+a.id+'|published">Publish</button>')+'</div></div>').join('')||'<p>No academic notices yet.</p>')+'</div>';
 const rr=()=>SEC.notices(v);
 const form=a=>ask((S.del=a&&{t:'announcements',id:a.id,n:'notice'},a?'Edit notice':'New academic notice'),'<label>Title<input name="title" required maxlength="180" value="'+esc(a&&a.title)+'"></label><div class="ac-row"><label>Programme<select name="p"><option value="">All students</option>'+progOpts(a&&a.audience_programme)+'</select></label><label>Year<select name="y">'+yearOpts(a&&a.audience_year,1)+'</select></label></div><label>Message<textarea name="b" rows="6" required maxlength="5000">'+esc(a&&a.body)+'</textarea></label><label>Status<select name="st">'+opts([['draft','Save as draft'],['published','Publish now']],a&&a.status==='published'?'published':'draft')+'</select></label>',async x=>{
  const pub=x.st.value==='published',row={title:x.title.value.trim(),body:x.b.value.trim(),category:'Academic',status:pub?'published':'draft',audience_programme:x.p.value||null,audience_year:x.y.value?+x.y.value:null,updated_at:new Date().toISOString()};
  if(pub&&!(a&&a.published_at))row.published_at=new Date().toISOString();if(!a)row.created_by=S.user.id;
  const z=await (a?db.from('announcements').update(row).eq('id',a.id).select('id'):db.from('announcements').insert(row).select('id'));if(z.error)throw z.error;if(!z.data||!z.data.length)throw new Error('Not saved. Check your permissions.');say(pub?'Notice published.':'Notice saved as draft.');rr()});
 $('nadd').onclick=()=>form(null);v.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>form(ann.find(x=>x.id===b.dataset.e)));
 v.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{const [id,st]=b.dataset.s.split('|');act(async()=>{const row={status:st,updated_at:new Date().toISOString()};if(st==='published')row.published_at=new Date().toISOString();const z=await db.from('announcements').update(row).eq('id',id).select('id');if(z.error)throw z.error;if(!z.data.length)throw new Error('Not updated.')},st==='published'?'Notice published.':'Notice archived.',rr)})};

